function t(k){return dict[state.language]?.[k]||dict.en[k]||k}
function isotopeLabel(value){return String(value).replace(/^([A-Za-z]+)(\d+)$/,'$1-$2')}
function localizeWarning(value){const text=String(value);if(state.language==='zh')return text;const rules={zht:[['未确认Ra/Th衰变链平衡，结果仅代表子体等效活度。','未確認 Ra/Th 衰變鏈平衡，結果僅代表子體等效活度。'],['死时间超过5%，需检查计数损失。','死時間超過 5%，需檢查計數損失。'],['能量刻度RMS残差超过0.5 keV。','能量刻度 RMS 殘差超過 0.5 keV。'],['K-40修正后净计数率不为正。','K-40 修正後淨計數率不為正。']],en:[['未确认Ra/Th衰变链平衡，结果仅代表子体等效活度。','Ra/Th chain equilibrium is unconfirmed; results represent daughter-equivalent activity only.'],['死时间超过5%，需检查计数损失。','Dead time exceeds 5%; check counting losses.'],['能量刻度RMS残差超过0.5 keV。','Energy-calibration RMS residual exceeds 0.5 keV.'],['K-40修正后净计数率不为正。','The corrected K-40 net count rate is not positive.']],fr:[['未确认Ra/Th衰变链平衡，结果仅代表子体等效活度。','Équilibre des chaînes Ra/Th non confirmé ; le résultat représente seulement une activité équivalente des descendants.'],['死时间超过5%，需检查计数损失。','Le temps mort dépasse 5 % ; vérifiez les pertes de comptage.'],['能量刻度RMS残差超过0.5 keV。','Le résidu RMS de l’étalonnage dépasse 0,5 keV.'],['K-40修正后净计数率不为正。','Le taux de comptage net corrigé de K-40 n’est pas positif.']]};let result=text;for(const [source,target] of rules[state.language]||[]){result=result.replace(source,target)}const peak=result.match(/^(Ra226|Th232|K40)可用峰少于2条，多峰一致性不足。$/);if(peak){const nuclide=isotopeLabel(peak[1]);return state.language==='zht'?`${nuclide} 可用峰少於 2 條，多峰一致性不足。`:state.language==='fr'?`Moins de deux raies utilisables pour ${nuclide} ; cohérence multiraie insuffisante.`:`Fewer than two usable ${nuclide} lines; multi-line consistency is insufficient.`}return result}
function formatText(key,values={}){return Object.entries(values).reduce((text,[name,value])=>text.replaceAll(`{${name}}`,String(value)),t(key))}
function renderParameterImportStatus(){const el=$('#parameterImportStatus');if(!state.parameterImport){el.textContent='';el.classList.remove('error');return}const item=state.parameterImport;el.classList.toggle('error',!item.ok);el.textContent=item.ok?formatText('parameterImportSuccess',{file:item.file,count:item.count}):formatText('parameterImportFailure',{error:item.error})}
function renderReportTemplateStatus(){const box=$('#reportTemplateStatus'),remove=$('#removeReportTemplate'),button=$('#exportTemplateReport'),item=state.reportTemplate;box.classList.toggle('ready',Boolean(item?.ok));box.classList.toggle('error',Boolean(item&&!item.ok));remove.disabled=!item?.ok;button.disabled=!(item?.ok&&state.analysis);if(!item){box.querySelector('b').textContent=t('noReportTemplate');box.querySelector('small').textContent=t('templatePlaceholderHint');button.querySelector('span').textContent=t('exportWithTemplate');return}if(item.inspecting){box.querySelector('b').textContent=t('templateInspecting');box.querySelector('small').textContent=item.file.name;return}if(!item.ok){box.querySelector('b').textContent=formatText('templateFailure',{error:item.error});box.querySelector('small').textContent=t('templatePlaceholderHint');return}const meta=item.meta,unknown=meta.unknown_tokens?.length||0;box.querySelector('b').textContent=formatText('templateReady',{file:item.file.name,count:meta.recognized_count});box.querySelector('small').textContent=(meta.recognized_tokens||[]).join(' · ')+(unknown?formatText('templateUnknown',{count:unknown}):'');button.querySelector('span').textContent=`${t('exportWithTemplate')} · ${meta.format.toUpperCase()}`}
function applyLanguage(){document.documentElement.lang=({zh:'zh-CN',zht:'zh-Hant',en:'en',fr:'fr'})[state.language];document.title=t('appTitle');$$('[data-i18n]').forEach(el=>el.textContent=t(el.dataset.i18n));$('#calSlope').placeholder=t('slope');$('#calIntercept').placeholder=t('intercept');if(!state.exportLanguageTouched)$('#exportLanguage').value=state.language;$$('[data-language]').forEach(el=>el.classList.toggle('active',el.dataset.language===state.language));$('#downloadExampleTemplate').href='/api/report-template/example/'+state.language;renderParameterImportStatus();renderReportTemplateStatus();renderExportLocation();updateCalSourceMode();renderSamples();if(state.analysis)renderResults(state.analysis)}
function renderSamples(){const box=$('#sampleList');if(!state.samples.length){box.innerHTML=`<p class="empty">${t('sampleEmpty')}</p>`;return}box.innerHTML=state.samples.map((item,i)=>{const status=item.inspecting?t('detectingLive'):(item.liveSource==='TREAL+DEADTIME'?t('liveDerived'):(item.liveSource?t('liveFromFile'):(item.inspected?t('liveMissing'):'')));return`<div class="sample-row"><span title="${escapeHtml(item.file.name)}">${escapeHtml(item.file.name)}</span><input class="mass" data-index="${i}" type="number" min="0" step="0.01" value="${item.mass}" title="${t('mass')}" placeholder="${t('mass')}"><label class="live-field ${item.liveSource?'detected':''}"><input class="live" data-index="${i}" type="number" min="0" step="any" value="${item.live}" title="${t('live')}" placeholder="${t('live')}"><small>${status}</small></label><button data-remove="${i}" title="${t('remove')}">×</button></div>`}).join('');$$('.mass').forEach(el=>el.oninput=e=>state.samples[+e.target.dataset.index].mass=e.target.value);$$('.live').forEach(el=>el.oninput=e=>{const item=state.samples[+e.target.dataset.index];item.live=e.target.value;item.liveSource='manual';const field=e.target.closest('.live-field');field.classList.remove('detected');field.querySelector('small').textContent=t('liveManual')});$$('[data-remove]').forEach(el=>el.onclick=e=>{state.samples.splice(+e.currentTarget.dataset.remove,1);renderSamples()})}
function escapeHtml(v){return String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function addSamples(files){const additions=[];for(const file of files){if(!state.samples.some(x=>x.file.name===file.name&&x.file.size===file.size)){const item={file,mass:'337.76',live:'',liveSource:'',inspecting:true,inspected:false};state.samples.push(item);additions.push(item)}}renderSamples();if(additions.length)inspectSamples(additions)}
async function inspectSamples(items){const form=new FormData();items.forEach(item=>form.append('files',item.file));try{const response=await fetch('/api/inspect',{method:'POST',body:form}),data=await response.json();if(!response.ok)throw new Error(data.detail||response.statusText);items.forEach((item,index)=>{const result=data.files[index]||{};if(result.live_time_s>0){item.live=String(result.live_time_s);item.liveSource=result.live_time_source||'TLIVE'}item.realTime=result.real_time_s;item.inspectError=result.error||'';item.inspected=true;item.inspecting=false})}catch(error){items.forEach(item=>{item.inspectError=error.message;item.inspected=true;item.inspecting=false})}renderSamples()}
function updateCalSourceMode(){const builtin=$('#calSourceMode').value==='default',input=$('#calFile'),drop=$('#calDrop');input.disabled=builtin;drop.classList.toggle('builtin',builtin);$('#calIcon').textContent=builtin?'✓':'＋';$('#calUploadText').textContent=builtin?t('defaultSourceReady'):t('calUpload');$('#calName').textContent=builtin?'土壤监测效率校准源.xls':(input.files[0]?.name||t('notSelected'))}
$('#calSourceMode').onchange=updateCalSourceMode;
$('#calFile').onchange=e=>{$('#calName').textContent=e.target.files[0]?.name||t('notSelected')};$('#sampleFiles').onchange=e=>addSamples(e.target.files);
[['#calDrop','#calFile'],['#sampleDrop','#sampleFiles']].forEach(([zone,input])=>{const z=$(zone);['dragenter','dragover'].forEach(ev=>z.addEventListener(ev,e=>{e.preventDefault();if(input==='#sampleFiles'||$('#calSourceMode').value==='upload')z.classList.add('drag')}));['dragleave','drop'].forEach(ev=>z.addEventListener(ev,e=>{e.preventDefault();z.classList.remove('drag')}));z.addEventListener('drop',e=>{if(input==='#sampleFiles')addSamples(e.dataTransfer.files);else if($('#calSourceMode').value==='upload'){const dt=new DataTransfer();dt.items.add(e.dataTransfer.files[0]);$(input).files=dt.files;$(input).dispatchEvent(new Event('change'))}})});
$('#resetBtn').onclick=()=>{[['#calMass','337.76'],['#refDate','2015-01-25'],['#raActivity','903'],['#thActivity','483'],['#kActivity','668'],['#roiWidth','2.4'],['#bgGap','1.5'],['#bgWidth','3.6'],['#calSlope',''],['#calIntercept','']].forEach(([s,v])=>$(s).value=v);$('#equilibrium').checked=true;$('#kCorrection').checked=true};
const parameterFields={calibration_mass_g:'#calMass',reference_date:'#refDate',ra_activity_bq:'#raActivity',th_activity_bq:'#thActivity',k_activity_bq:'#kActivity',roi_half_width_keV:'#roiWidth',background_gap_keV:'#bgGap',background_width_keV:'#bgWidth',calibration_slope:'#calSlope',calibration_intercept:'#calIntercept'};
function fillImportedParameters(values){for(const [key,selector] of Object.entries(parameterFields)){if(values[key]!==undefined&&values[key]!==null)$(selector).value=values[key]}if(values.assume_chain_equilibrium!==undefined)$('#equilibrium').checked=Boolean(values.assume_chain_equilibrium);if(values.correct_k_interference!==undefined)$('#kCorrection').checked=Boolean(values.correct_k_interference);if(['background_gap_keV','background_width_keV','calibration_slope','calibration_intercept'].some(key=>values[key]!==undefined))$('.advanced').open=true}
const parameterFile=$('#parameterFile'),parameterButton=$('#parameterImportBtn');parameterButton.onclick=()=>parameterFile.click();parameterFile.onchange=async()=>{const file=parameterFile.files[0];if(!file)return;parameterButton.disabled=true;state.parameterImport=null;const status=$('#parameterImportStatus');status.classList.remove('error');status.textContent=t('parameterImporting');try{const body=new FormData();body.append('file',file);const response=await fetch('/api/import-parameters',{method:'POST',body}),data=await response.json();if(!response.ok)throw new Error(data.detail||response.statusText);fillImportedParameters(data.values);state.parameterImport={ok:true,file:data.filename,count:data.recognized_count};renderParameterImportStatus()}catch(error){state.parameterImport={ok:false,error:error.message};renderParameterImportStatus()}finally{parameterButton.disabled=false;parameterFile.value=''}};
function fileAsBase64(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',',2)[1]||'');reader.onerror=()=>reject(reader.error||new Error('FileReader failed'));reader.readAsDataURL(file)})}
async function loadReportTemplate(file){if(!file)return;if(file.size>25*1024*1024){state.reportTemplate={ok:false,error:'Template exceeds 25 MB'};renderReportTemplateStatus();return}state.reportTemplate={file,inspecting:true,ok:false};renderReportTemplateStatus();try{const body=new FormData();body.append('file',file);const response=await fetch('/api/report-template/inspect',{method:'POST',body}),data=await response.json();if(!response.ok)throw new Error(data.detail||response.statusText);state.reportTemplate={file,base64:await fileAsBase64(file),meta:data,ok:true,inspecting:false}}catch(error){state.reportTemplate={file,error:error.message,ok:false,inspecting:false}}renderReportTemplateStatus()}
