function num(v,d=4){return typeof v==='number'&&Number.isFinite(v)?v.toPrecision(d):'—'}
function reportableActivity(r,key){const q=r.quality?.nuclides?.[key];return q?q.reportable_activity_bq_kg:r.activity_bq_kg?.[key]}
