  const referenceRows=data.peak_references.map(p=>`<tr><td>${isotopeLabel(p.nuclide)} (${p.emitter})</td><td>${num(p.energy_keV,7)}</td><td>≈ ${p.default_reference_channel}</td></tr>`).join('');
